ALTER POLICY upload_vigilance_audio ON storage.objects WITH CHECK(bucket_id='lead-audio' AND public.crm_role()='vigilance' AND (storage.foldername(storage.objects.name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.leads l WHERE l.id::text=(storage.foldername(storage.objects.name))[2] AND l.stage='vigilance'));
ALTER POLICY read_own_pending_audio ON storage.objects USING(bucket_id='lead-audio' AND public.crm_role()='vigilance' AND (storage.foldername(storage.objects.name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.leads l WHERE l.id::text=(storage.foldername(storage.objects.name))[2] AND l.stage='vigilance'));
ALTER POLICY read_department_audio ON storage.objects USING(bucket_id='lead-audio' AND public.crm_role() IS NOT NULL AND EXISTS(SELECT 1 FROM public.leads l WHERE l.audio_path=storage.objects.name AND (public.crm_role()<>'sales' OR (l.stage='sales' AND (l.claimed_by IS NULL OR l.claimed_by=auth.uid())))));
